SELECT 'PER_PEOPLE' key,'PERSON_ID'||'~'||'PERSON_NUMBER'||'~'||'PRIMARY_EMAIL_ID'||'~'||'PRIMARY_PHONE_ID'||'~'||'REGION_OF_BIRTH'||'~'|| 'START_DATE'||'~'|| 'DATE_OF_BIRTH'||'~'||'TOWN_OF_BIRTH'||'~'|| 'WAIVE_DATA_PROTECT'||'~'|| 'PARTY_ID'||'~'|| 'BLOOD_TYPE'||'~'|| 'BUSINESS_GROUP_ID'||'~'||
       'COUNTRY_OF_BIRTH'||'~'|| 'CREATED_BY'||'~'|| 'CREATION_DATE'||'~'|| 'LAST_UPDATE_DATE'||'~'|| 'LAST_UPDATE_LOGIN'||'~'|| 'LAST_UPDATED_BY'||'~'|| 'OBJECT_VERSION_NUMBER'||'~'||'APPLICANT_NUMBER' PER_PEOPLE
FROM DUAL
UNION ALL
SELECT 'PER_PEOPLE' key,PERSON_ID||','||PERSON_NUMBER||','|| PRIMARY_EMAIL_ID||','|| PRIMARY_PHONE_ID||','|| REGION_OF_BIRTH||','|| START_DATE||','|| DATE_OF_BIRTH||','||TOWN_OF_BIRTH||','|| WAIVE_DATA_PROTECT||','|| PARTY_ID||','|| BLOOD_TYPE||','|| BUSINESS_GROUP_ID||','||
       COUNTRY_OF_BIRTH||','|| CREATED_BY||','|| CREATION_DATE||','|| LAST_UPDATE_DATE||','|| LAST_UPDATE_LOGIN||','|| LAST_UPDATED_BY||','|| OBJECT_VERSION_NUMBER||','||APPLICANT_NUMBER
FROM PER_PEOPLE_F a
WHERE a.last_update_date between sysdate-7 AND sysdate-1